style.css:
@-moz-document domain("roblox.com") {
html, body {
        background-image: url("https://i.imgur.com/SC6PCZ9.jpeg") !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-position: center center !important;
        background-attachment: fixed !important;
        color: #ffffff !important;
    }

    .navbar, .header, .footer, .container-header, .container-footer,
    .content, .section, .card, .game-card-container, .content-bg, .game-card, .home-container {
        background-color: rgba(0, 0, 0, 0.6) !important;
        backdrop-filter: blur(6px) !important;
        border-radius: 12px !important;
        box-shadow: 0 0 10px rgba(255, 255, 255, 0.05);
    }

    .btn-primary, .btn-secondary, .btn-control-md, .btn-growth-md {
        background-color: #ff66a3 !important;
        border: none !important;
        color: white !important;
    }

    a, .text-link, .text-name {
        color: #ffd1dc !important;
    }

    body {
        font-family: "Comic Sans MS", "Segoe UI", sans-serif !important;
    }
}
